"""Differential test: project C pipeline vs dev/reference model."""
import json, random, subprocess, sys, os
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__))))
import ref

PRIMS = ['allreduce', 'reduce', 'broadcast', 'barrier', 'allgather', 'reducescatter']

def gen_case(rnd, heavy=False):
    kind = rnd.choice(PRIMS)
    mode = rnd.choice([2, 3])
    root = rnd.randrange(4)
    if kind == 'barrier':
        K, D = 1, 0
    else:
        D = rnd.choice([1, 1, 2, 3, 5]) if not heavy else rnd.randrange(1, 1025)
        if kind == 'reducescatter':
            K = rnd.choice([4, 8, 12, 16, 64, 100])
        else:
            K = rnd.choice([1, 2, 3, 4, 5, 8, 13])
    N = rnd.choice([1, 2, 3, 4, 5, 8, 16, 64])
    start = rnd.choice([0, 1, 7, 0x00fffff0, 0x800000, rnd.randrange(1 << 24)])
    events = []
    used = 0
    span = 2 if rnd.random() < 0.5 else 0

    def psn(p):
        return (start + p) % (1 << 24)

    nops = rnd.randrange(0, 14)
    for _ in range(nops):
        pick = rnd.random()
        if pick < 0.34:
            p = rnd.randrange(K)
            rank = rnd.randrange(4)
            if rnd.random() < 0.3:
                count = rnd.randrange(1, 4)
                step = rnd.choice([-1, 0, 1, 2])
                if not (0 <= p + (count - 1) * step < K):
                    continue
                ev = {'op': 'data', 'rank': rank, 'p': p, 'count': count, 'step': step}
                if D and rnd.random() < 0.3:
                    ev['values'] = [rnd.randrange(1 << 32) for _ in range(D)]
                events.append(ev)
            else:
                ev = {'op': 'data', 'rank': rank, 'p': p}
                if rnd.random() < 0.25:
                    ev['seed'] = rnd.randrange(1 << 32)
                if D and rnd.random() < 0.3:
                    ev['values'] = [rnd.randrange(1 << 32) for _ in range(D)]
                events.append(ev)
        elif pick < 0.5:
            events.append({'op': 'ack', 'rank': rnd.randrange(4),
                           'upto': rnd.choice([0, 1, rnd.randrange(0, 3 * K + 2)])})
        elif pick < 0.58:
            events.append({'op': 'flush'})
        elif pick < 0.68:
            events.append({'op': 'retry', 'rank': rnd.randrange(4)})
        elif pick < 0.76:
            events.append({'op': 'budget', 'n': rnd.choice([-1, 0, 1, 2, 3, 7, 100])})
        elif pick < 0.82:
            events.append({'op': 'snap', 'tag': 's%d' % rnd.randrange(10)})
        elif pick < 0.9:
            events.append({'op': 'wire', 'rank': rnd.randrange(4),
                           'hex': rnd.choice(['', '00', 'ff' * 60, corrupt(rnd, kind, D, psn)])})
        else:
            if kind == 'barrier' or heavy:
                continue
            count = rnd.randrange(1, min(6, K + 1))
            p = rnd.randrange(0, K - count + 1)
            events.append({'op': 'train', 'p': p, 'count': count,
                           'width': rnd.randrange(1, N + 1),
                           'ranks': rnd.sample([0, 1, 2, 3], 4),
                           'reverse': rnd.random() < 0.3,
                           'seed': rnd.randrange(1 << 32) if rnd.random() < 0.3 else 0})
    # xor corruption on a data event sometimes
    for ev in events:
        if ev['op'] == 'data' and rnd.random() < 0.12:
            off = rnd.randrange(0, 58 + 4 * D - 1)
            ev['xor'] = [[off, rnd.randrange(256)]]
    case = {'primitive': kind, 'mode': mode, 'root': root, 'segments': K,
            'words': D, 'capacity': N, 'start': start, 'events': events}
    if rnd.random() < 0.7:
        case['trace'] = rnd.randrange(0, 33)
    return case


def corrupt(rnd, kind, D, psnfn):
    import sys as _s
    _s.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'project'))
    from wire import packet, payload
    f = bytearray(packet(0, 0, payload(0, 0, 0, max(D, 1))))
    for _ in range(rnd.randrange(1, 3)):
        f[rnd.randrange(len(f))] ^= 1 << rnd.randrange(8)
    return f.hex()


def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    rounds = int(sys.argv[2]) if len(sys.argv) > 2 else 40
    rnd = random.Random(seed)
    bad = 0
    for it in range(rounds):
        req = {'cases': [gen_case(rnd) for _ in range(rnd.randrange(1, 4))]}
        raw = json.dumps(req).encode()
        want = ref.solve(json.loads(raw))
        p = subprocess.run([sys.executable, '-I', '-B', 'project/solver.py'], input=raw,
                           stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd='/workspace')
        if p.returncode:
            print('round', it, 'solver failed', p.stderr.decode()[:800]); bad += 1; continue
        got = json.loads(p.stdout.decode())
        for i, (g, w) in enumerate(zip(got['cases'], want['cases'])):
            if g != w:
                bad += 1
                print('MISMATCH round %d case %d' % (it, i))
                kind = req['cases'][i]['primitive']
                print(' kind', kind, 'mode', req['cases'][i]['mode'], 'root', req['cases'][i]['root'],
                      'K', req['cases'][i]['segments'], 'D', req['cases'][i]['words'],
                      'N', req['cases'][i]['capacity'], 'start', req['cases'][i]['start'])
                for k in g:
                    if g[k] != w[k]:
                        print('   field', k)
                        if k == 'state':
                            for a, b in zip(g[k], w[k]):
                                if a != b:
                                    print('     got', g[k]); print('     want', w[k]); break
                        else:
                            print('     got', str(g[k])[:300]); print('     want', str(w[k])[:300])
                open('/workspace/dev/fail-%d-%d.json' % (it, i), 'wb').write(raw)
        if bad:
            break
    print('done, mismatches:', bad)


if __name__ == '__main__':
    main()
